# Expected values generated by test/torch/gen_nn_expected.py (torch 2.15.0).
import torch
import torch.nn as nn
import torch.nn.functional as F

def X(shape: List[int], seed: int, dtype = torch.float64) -> torch.Tensor:
    n = 1
    for s in shape: n *= s
    return ((torch.arange(n, dtype=torch.float64) * 0.37 + float(seed)).sin() * 2.0).reshape(shape).to(dtype)

def close(t: torch.Tensor, exp: List[float], rtol: float) -> bool:
    v = t.detach().contiguous().reshape([-1]).double().tolist()
    if len(v) != len(exp):
        print("len mismatch", len(v), len(exp))
        return False
    scale = 0.0
    for e in exp: scale = max(scale, abs(e))
    for i in range(len(v)):
        if abs(v[i] - exp[i]) > rtol * max(abs(exp[i]), 1e-3 * scale):
            print("mismatch at", i, v[i], exp[i])
            return False
    return True

def closef(a: float, b: float, rtol: float) -> bool:
    return abs(a - b) <= rtol * abs(b)
from torch.nn.utils import parametrize as P
from torch.nn.utils.parametrizations import weight_norm

class MaxNorm(nn.Module):
    m: float
    def __init__(self, m: float):
        super().__init__()
        self.m = m
    def forward(self, X: torch.Tensor) -> torch.Tensor:
        n = X.reshape([X.size(0), -1]).norm(2, 1, keepdim=True)
        d = n.clamp(self.m / 2, None)
        num = d.clamp(None, self.m)
        return X * (num / (d + 1e-5)).reshape([-1] + [1] * (X.dim() - 1))

@test
def test_init_parity():
    # bit-exact default init through torch's MT19937 stream
    torch.manual_seed(0)
    c = nn.Conv2d(2, 3, (1, 3))
    l = nn.Linear(4, 2)
    assert close(c.weight, [-0.0030564817134290934, 0.21900218725204468, -0.3360067903995514, -0.3004458546638489, -0.15723861753940582, 0.1094747856259346, -0.008088696748018265, 0.3236957788467407, -0.036229606717824936, 0.1080276295542717, -0.1233779713511467, -0.08024748414754868, -0.39001941680908203, -0.2703755497932434, -0.16828937828540802, 0.0151229752227664, 0.16139492392539978, 0.2449582815170288], 0.0)  # conv_w
    assert close(c.bias.__val__(), [-0.276768296957016, -0.17777696251869202, 0.14828276634216309], 0.0)  # conv_b
    assert close(l.weight, [0.41519397497177124, -0.10290008783340454, 0.3741558790206909, -0.08059167861938477, 0.05290704965591431, 0.45273810625076294, -0.4638351798057556, -0.3147689700126648], 0.0)  # lin_w
    assert close(l.bias.__val__(), [-0.12658262252807617, -0.19489997625350952], 0.0)  # lin_b
    assert close(torch.rand([3]), [0.9320003986358643, 0.17591017484664917, 0.2698335647583008], 0.0)  # after
    w = torch.empty([3, 5])
    assert nn.init._calculate_fan_in_and_fan_out(torch.empty([4, 3, 2, 5])) == (30, 40)
    assert abs(nn.init.calculate_gain("leaky_relu", 0.2) - 1.3867504905630728) < 1e-15

@test
def test_parametrize():
    torch.manual_seed(0)
    lin = nn.Linear(5, 3)
    P.register_parametrization(lin, "weight", MaxNorm(0.5))
    assert list(lin.state_dict().keys()) == ['bias', 'parametrizations.weight.original']  # ptz_keys
    assert close(lin.weight, [-0.0029096254147589207, 0.20847967267036438, -0.3198625147342682, -0.286010205745697, -0.14968368411064148, 0.11992056667804718, -0.008860497735440731, 0.35458195209503174, -0.03968653455376625, 0.11833532899618149, -0.11759123206138611, -0.07648366689682007, -0.37172648310661316, -0.2576942443847656, -0.16039617359638214], 1e-6)  # ptz_w
    lin(torch.ones([2, 5])).sum().backward()
    g = lin.get_submodule("parametrizations.weight")
    assert close(g.get_parameter("original").grad.__val__(), [1.7268942594528198, 2.535165548324585, 0.5149886608123779, 0.644426703453064, 1.165686845779419, 1.999970555305481, 1.9999476671218872, 2.000012159347534, 1.9999421834945679, 1.9999701976776123, 0.9347934722900391, 1.2163162231445312, -0.8056364059448242, -0.02469336986541748, 0.6416463851928711], 1e-4)  # ptz_grad
    assert P.is_parametrized(lin, "weight")

@test
def test_weight_norm():
    torch.manual_seed(0)
    c = weight_norm(nn.Conv1d(2, 3, 2))
    assert list(c.state_dict().keys()) == ['bias', 'parametrizations.weight.original0', 'parametrizations.weight.original1']  # wn_keys
    y = c(X([1, 2, 4], 14, torch.float32))
    y.sum().backward()
    assert close(y, [-0.04494616389274597, 0.4340130686759949, 0.7895798683166504, -0.5684750080108643, -0.8706871271133423, -1.0998742580413818, -0.0770222544670105, 0.06459811329841614, 0.16957920789718628], 1e-5)  # wn_y
    assert close(c.get_parameter("parametrizations.weight.original0").grad.__val__(), [4.255151748657227, -3.354250907897949, 3.401843547821045], 1e-5)  # wn_g0
    assert close(c.get_parameter("parametrizations.weight.original1").grad.__val__(), [5.60066556930542, 2.859877109527588, 2.0419857501983643, -0.25601911544799805, 4.172883987426758, 5.6954193115234375, -0.8831520676612854, 0.07874751091003418, 6.236870765686035, 2.745028257369995, 1.443905234336853, -1.3404362201690674], 1e-5)  # wn_g1

@test
def test_clip_grad_norm():
    torch.manual_seed(0)
    lin = nn.Linear(4, 3).double()
    ((lin(X([2, 4], 15)) ** 2).sum()).backward()
    tn = nn.utils.clip_grad_norm_(lin.parameters(), 0.5)
    assert closef(tn.item(), 9.238404548856355, 1e-13)  # clip_total
    assert close(lin.weight.grad.__val__(), [-0.08349452101753237, -0.10993399307103767, -0.12149441488605296, -0.1166111376023065, 0.04431859032518732, 0.14744514351246, 0.23061568822175807, 0.2825734813973409, -0.02829657611661299, -0.02689007901006214, -0.021844135856562513, -0.01384169139035096], 1e-12)  # clip_gw

test_init_parity()
test_parametrize()
test_weight_norm()
test_clip_grad_norm()
